          "ci_css": "",
          "ci_head": "\u003ciframe\u003e\n  \u003c!DOCTYPE html\u003e\n\u003chtml lang=\"hr\"\u003e\n\u003chead\u003e\n\u003cmeta charset=\"UTF-8\" /\u003e\n\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" /\u003e\n\u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\" /\u003e\n\u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin /\u003e\n\u003clink href=\"https://fonts.googleapis.com/css2?family=Anton\u0026family=Inter:wght@400\u0026display=swap\" rel=\"stylesheet\" /\u003e\n\u003cstyle\u003e\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  html, body { width: 100%; height: 100%; }\n  body { background: #f5f6e4; font-family: 'Anton', sans-serif; -webkit-font-smoothing: antialiased; }\n  #root { width: 100%; min-height: 100vh; }\n  .screen { min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #f5f6e4; padding: 2rem 1.5rem; text-align: center; }\n  .intro-title { font-family: 'Anton', sans-serif; color: #e33c12; font-size: clamp(1.5rem, 4vw, 3rem); line-height: 1.1; text-transform: uppercase; margin-bottom: 1rem; max-width: 600px; }\n  .intro-subtitle { font-family: 'Inter', sans-serif; color: #e33c12; font-size: clamp(0.8rem, 1.5vw, 1rem); line-height: 1.5; max-width: 480px; margin-bottom: 2rem; font-weight: 400; }\n  .btn { display: inline-block; background: #e33c12; color: #f5f6e4; font-family: 'Anton', sans-serif; font-size: clamp(0.85rem, 1.8vw, 1.2rem); text-transform: uppercase; border: none; border-radius: 9999px; padding: 0.7rem 2.5rem; cursor: pointer; transition: filter .15s, transform .1s; }\n  .btn:hover { filter: brightness(0.88); }\n  .btn:active { transform: scale(0.97); }\n  .btn:disabled { opacity: .38; cursor: not-allowed; filter: none; transform: none; }\n  .question-wrap { width: 100%; max-width: 560px; text-align: left; }\n  .question-title { font-family: 'Anton', sans-serif; color: #e33c12; font-size: clamp(1.2rem, 3vw, 2rem); text-transform: uppercase; line-height: 1.15; margin-bottom: 1.2rem; }\n  .answers { display: flex; flex-direction: column; gap: 0.5rem; margin-bottom: 1.5rem; }\n  .answer-btn { width: 100%; text-align: left; background: #e33c12; color: #f5f6e4; font-family: 'Anton', sans-serif; font-size: clamp(0.75rem, 1.4vw, 1rem); border: 3px solid transparent; border-radius: 8px; padding: 0.6rem 1rem; cursor: pointer; transition: filter .15s, border-color .15s, background .15s, color .15s; line-height: 1.3; }\n  .answer-btn:hover { filter: brightness(0.88); }\n  .answer-btn.selected { background: #f5f6e4; color: #e33c12; border-color: #e33c12; filter: none; }\n  .btn-center { display: flex; justify-content: center; }\n  .result-title { font-family: 'Anton', sans-serif; color: #e33c12; font-size: clamp(1.5rem, 4vw, 3rem); text-transform: uppercase; line-height: 1.1; margin-bottom: 1rem; max-width: 600px; }\n  .result-desc { font-family: 'Anton', sans-serif; color: #e33c12; font-size: clamp(0.8rem, 1.4vw, 1rem); line-height: 1.55; max-width: 500px; margin-bottom: 2rem; }\n\u003c/style\u003e\n\u003c/head\u003e\n\u003cbody\u003e\n\u003cdiv id=\"root\"\u003e\u003c/div\u003e\n\u003cscript\u003e\nconst FLAVOR_MAP = { A:\"Duo\", B:\"Milk\", C:\"Gold\", D:\"GoldCreamy\", E:\"Kokos\" };\nconst RESULTS = {\n  Gold: { title:\"Ti si Lino Lada Gold\", description:'Kod tebe sve mora imati malo više karaktera. Voliš bogate okuse, lješnjake, teksturu i onaj trenutak kad desert ima nešto posebno. Lino Lada Gold, sa 16 posto lješnjaka i komadićima sjeckanih lješnjaka, savršeno paše tvom \"daj mi nešto konkretno\" stilu.' },\n  GoldCreamy: { title:\"Ti si Lino Lada Gold Creamy\", description:\"Ti voliš bogato, ali glatko. Kod tebe je sve u teksturi, balansu i onom savršeno kremastom zalogaju koji se lako uklopi u palačinke, croissante, kolače ili žlicu. Lino Lada Gold Creamy je tvoj izbor jer ima puni okus lješnjaka, ali bez hrskavih prekida.\" },\n  Kokos: { title:\"Ti si Lino Lada Kokos\", description:\"Ti si ljetni tip, čak i kad je vani oblačno. Voliš okuse koji podsjećaju na more, sunce i lagane slatke trenutke bez puno plana. Lino Lada Kokos, s harmonijom mlijeka i kokosa, tvoj je savršeni match za dane kad želiš da sve ima malo tropskiji vibe.\" },\n  Duo: { title:\"Ti si Lino Lada Duo\", description:\"Ti si klasik s razlogom. Voliš stvari koje imaju priču, okus djetinjstva i onaj prepoznatljivi spoj bijelog i tamnog namaza kojem se uvijek vraćamo. Kod tebe nema puno filozofije: kad je nešto dobro, dobro je zauvijek.\" },\n  Milk: { title:\"Ti si Lino Lada Milk\", description:\"Ti si onaj tip koji je oduvijek prvo išao na bijeli dio. Voliš nježne, mliječne okuse i slatke rituale koji nisu prenapadni, nego baš fino kremasti i lagani. Tvoj idealan trenutak je jednostavan, mekan i sladak taman koliko treba.\" }\n};\nconst QUESTIONS = [\n  { number:1, question:\"Kako izgleda tvoje savršeno jutro?\", answers:[{key:\"A\",text:\"Tost, kava i onaj poznati okus koji te odmah vrati u djetinjstvo\"},{key:\"B\",text:\"Lagano, nježno i bez puno kompliciranja\"},{key:\"C\",text:\"Bogato, sporo i s doručkom koji se ne zaboravlja\"},{key:\"D\",text:\"Glatko, kremasto i baš po mom ukusu\"},{key:\"E\",text:\"Sunce, ljeto, otvoren prozor i nešto slatko za početak dana\"}], buttonLabel:\"IDUĆE PITANJE\" },\n  { number:2, question:\"Koji desert te najbolje opisuje?\", answers:[{key:\"A\",text:\"Palačinke s klasičnim namazom\"},{key:\"B\",text:\"Mliječni cheesecake\"},{key:\"C\",text:\"Čokoladni tart s lješnjacima\"},{key:\"D\",text:\"Kremasti mousse od lješnjaka\"},{key:\"E\",text:\"Kokos kocke ili sladoled od kokosa\"}], buttonLabel:\"IDUĆE PITANJE\" },\n  { number:3, question:\"Kako najčešće jedeš Lino Ladu?\", answers:[{key:\"A\",text:\"Na kruhu, baš kako se jela uvijek\"},{key:\"B\",text:\"Tako da prvo tražim bijeli dio\"},{key:\"C\",text:\"Na palačinkama, uz još malo hrskavog dodatka\"},{key:\"D\",text:\"U desertima, kremama i svemu što traži glatku teksturu\"},{key:\"E\",text:\"Na žlicu, najbolje kad me uhvati ljetni mood\"}], buttonLabel:\"IDUĆE PITANJE\" },\n  { number:4, question:\"Koja rečenica te najbolje opisuje?\", answers:[{key:\"A\",text:\"Volim klasike i teško im odolijevam\"},{key:\"B\",text:\"Nježni okusi su mi uvijek prvi izbor\"},{key:\"C\",text:\"Ako je slatko, neka bude bogato i konkretno\"},{key:\"D\",text:\"Volim sve što je profinjeno, kremasto i fino izbalansirano\"},{key:\"E\",text:\"Najbolje stvari imaju okus ljeta\"}], buttonLabel:\"ZAVRŠI KVIZ\" }\n];\nfunction computeResult(a){const c={Duo:0,Milk:0,Gold:0,GoldCreamy:0,Kokos:0};for(const x of a)c[FLAVOR_MAP[x]]++;return Object.entries(c).sort((a,b)=\u003eb[1]-a[1])[0][0];}\nlet state={screen:\"intro\",answers:[],selected:null};\nfunction setState(p){state=Object.assign({},state,p);render();}\nfunction render(){\n  const root=document.getElementById(\"root\");\n  if(state.screen===\"intro\"){\n    root.innerHTML=`\u003cdiv class=\"screen\"\u003e\u003ch1 class=\"intro-title\"\u003eZABAVNI KVIZ: KOJI SI OKUS LINOLADE?\u003c/h1\u003e\u003cp class=\"intro-subtitle\"\u003eOvaj kviz otkriva koji Lino Lada namaz najbolje paše tvojoj osobnosti, jutarnjim ritualima i slatkim navikama. Odgovori na pitanja i saznaj baš svoj namaz.\u003c/p\u003e\u003cbutton class=\"btn\" id=\"s\"\u003eZAPOČNI KVIZ\u003c/button\u003e\u003c/div\u003e`;\n    document.getElementById(\"s\").onclick=()=\u003esetState({screen:0,answers:[],selected:null});return;\n  }\n  if(state.screen===\"result\"){\n    const r=RESULTS[computeResult(state.answers)];\n    root.innerHTML=`\u003cdiv class=\"screen\"\u003e\u003ch1 class=\"result-title\"\u003e${r.title}\u003c/h1\u003e\u003cp class=\"result-desc\"\u003e${r.description}\u003c/p\u003e\u003cbutton class=\"btn\" id=\"r\"\u003eVRATI NA KVIZ\u003c/button\u003e\u003c/div\u003e`;\n    document.getElementById(\"r\").onclick=()=\u003esetState({screen:\"intro\",answers:[],selected:null});return;\n  }\n  const q=QUESTIONS[state.screen];\n  root.innerHTML=`\u003cdiv class=\"screen\"\u003e\u003cdiv class=\"question-wrap\"\u003e\u003ch2 class=\"question-title\"\u003e${q.number}. ${q.question}\u003c/h2\u003e\u003cdiv class=\"answers\"\u003e${q.answers.map(({key,text})=\u003e`\u003cbutton class=\"answer-btn${state.selected===key?\" selected\":\"\"}\" data-key=\"${key}\"\u003e${key}) ${text}\u003c/button\u003e`).join(\"\")}\u003c/div\u003e\u003cdiv class=\"btn-center\"\u003e\u003cbutton class=\"btn\" id=\"n\" ${state.selected?\"\":\"disabled\"}\u003e${q.buttonLabel}\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\u003c/div\u003e`;\n  root.querySelectorAll(\".answer-btn\").forEach(b=\u003e{b.onclick=()=\u003esetState({selected:b.dataset.key});});\n  document.getElementById(\"n\").onclick=()=\u003e{if(!state.selected)return;const a=[...state.answers,state.selected];setState({screen:state.screen\u003c3?state.screen+1:\"result\",answers:a,selected:null});};\n}\nrender();\n\u003c/script\u003e\n\u003c/body\u003e\n\u003c/html\u003e\n\u003c/iframe\u003e",
