              "autosize": true,
              "blocks": [{
                "key": "furtd",
                "text": "Lino Lada je jedan od onih okusa koji se ne zaboravljaju. Nekad je bila namaz na palačinkama koje je pekla baka, nekad brz doručak na kruhu, a danas mali slatki ritual kojem se vraćamo kad nam treba nešto poznato, kremasto i baš naše.",
                "entityRanges": [{
                  "offset": 0,
                  "length": 9,
                  "key": 0
                }],
                "depth": 0
              }, {
                "key": "eaajp",
                "text": "",
                "entityRanges": [],
                "depth": 0
              }, {
                "key": "3e0l5",
                "text": "Ovdje na jednom mjestu istražujemo sve okuse koje volimo, od legendarne bijele i tamne kombinacije, preko kokosa i mliječnog klasika, do bogatog Gold namaza s lješnjacima. Jer svatko ima svoj način, svoj favorit i svoj savršeni zalogaj. Koji je tvoj?",
                "entityRanges": [{
                  "offset": 237,
                  "length": 13,
                  "key": 1
                }],
                "depth": 0
              }],
