p(1.2rem, 3vw, 2rem); text-transform: uppercase; line-height: 1.15; margin-bottom: 1.2rem; }\n  .answers { display: flex; flex-direction: column; gap: 0.5rem; margin-bottom: 1.5rem; }\n  .answer-btn { width: 100%; text-align: left; background: #e33c12; color: #f5f6e4; font-family: 'Anton', sans-serif; font-size: clamp(0.75rem, 1.4vw, 1rem); border: 3px solid transparent; border-radius: 8px; padding: 0.6rem 1rem; cursor: pointer; transition: filter .15s, border-color .15s, background .15s, color .15s; line-height: 1.3; }\n  .answer-btn:hover { filter: brightness(0.88); }\n  .answer-btn.selected { background: #f5f6e4; color: #e33c12; border-color: #e33c12; filter: none; }\n  .btn-center { display: flex; justify-content: center; }\n  .result-title { font-family: 'Anton', sans-serif; color: #e33c12; font-size: clamp(1.5rem, 4vw, 3rem); text-transform: uppercase; line-height: 1.1; margin-bottom: 1rem; max-width: 600px; }\n  .result-desc { font-family: 'Anton', sans-serif; color: #e33c12; font-size: clamp(0.8rem, 1.4vw, 1rem); line-height: 1.55; max-width: 500px; margin-bottom: 2rem; }\n\u003c/style\u003e\n\u003c/head\u003e\n\u003cbody\u003e\n\u003cdiv id=\"root\"\u003e\u003c/div\u003e\n\u003cscript\u003e\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n\n  var FLAVOR_MAP = { A:\"Duo\", B:\"Milk\", C:\"Gold\", D:\"GoldCreamy\", E:\"Kokos\" };\n\n  var RESULTS = {\n    Gold:       { title:\"Ti si Lino Lada Gold\",        description:\"Kod tebe sve mora imati malo više karaktera. Voliš bogate okuse, lješnjake, teksturu i onaj trenutak kad desert ima nešto posebno. Lino Lada Gold, sa 16 posto lješnjaka i komadićima sjeckanih lješnjaka, savršeno paše tvom \\\"daj mi nešto konkretno\\\" stilu.\" },\n    GoldCreamy: { title:\"Ti si Lino Lada Gold Creamy\", description:\"Ti voliš bogato, ali glatko. Kod tebe je sve u teksturi, balansu i onom savršeno kremastom zalogaju koji se lako uklopi u palačinke, croissante, kolače ili žlicu. Lino Lada Gold Creamy je tvoj izbor jer ima puni okus lješnjaka, ali bez hrskavih prekida.\" },\n    Kokos:      { title:\"Ti si Lino Lada Kokos\",       description:\"Ti si ljetni tip, čak i kad je vani oblačno. Voliš okuse koji podsjećaju na more, sunce i lagane slatke trenutke bez puno plana. Lino Lada Kokos, s harmonijom mlijeka i kokosa, tvoj je savršeni match za dane kad želiš da sve ima malo tropskiji vibe.\" },\n    Duo:        { title:\"Ti si Lino Lada Duo\",         description:\"Ti si klasik s razlogom. Voliš stvari koje imaju priču, okus djetinjstva i onaj prepoznatljivi spoj bijelog i tamnog namaza kojem se uvijek vraćamo. Kod tebe nema puno filozofije: kad je nešto dobro, dobro je zauvijek.\" },\n    Milk:       { title:\"Ti si Lino Lada Milk\",        description:\"Ti si onaj tip koji je oduvijek prvo išao na bijeli dio. Voliš nježne, mliječne okuse i slatke rituale koji nisu prenapadni, nego baš fino kremasti i lagani. Tvoj idealan trenutak je jednostavan, mekan i sladak taman koliko treba.\" }\n  };\n\n  var QUESTIONS = [\n    { number:1, question:\"Kako izgleda tvoje savršeno jutro?\", buttonLabel:\"IDUĆE PITANJE\", answers:[\n      { key:\"A\", text:\"Tost, kava i onaj poznati okus koji te odmah vrati u djetinjstvo\" },\n      { key:\"B\", text:\"Lagano, nježno i bez puno kompliciranja\" },\n      { key:\"C\", text:\"Bogato, sporo i s doručkom koji se ne zaboravlja\" },\n      { key:\"D\", text:\"Glatko, kremasto i baš po mom ukusu\" },\n      { key:\"E\", text:\"Sunce, ljeto, otvoren prozor i nešto slatko za početak dana\" }\n    ]},\n    { number:2, question:\"Koji desert te najbolje opisuje?\", buttonLabel:\"IDUĆE PITANJE\", answers:[\n      { key:\"A\", text:\"Palačinke s klasičnim namazom\" },\n      { key:\"B\", text:\"Mliječni cheesecake\" },\n      { key:\"C\", text:\"Čokoladni tart s lješnjacima\" },\n      { key:\"D\", text:\"Kremasti mousse od lješnjaka\" },\n      { key:\"E\", text:\"Kokos kocke ili sladoled od kokosa\" }\n    ]},\n    { number:3, question:\"Kako najčešće jedeš Lino Ladu?\", buttonLabel:\"IDUĆE PITANJE\", answers:[\n      { key:\"A\", text:\"Na kruhu, baš kako se jela uvijek\" },\n      { key:\"B\", text:\"Tako da prvo tražim bijeli dio\" },\n      { key:\"C\", text:\"Na palačinkama, uz još malo hrskavog dodatka\" },\n      { key:\"D\", text:\"U desertima, kremama i svemu što traži glatku teksturu\" },\n      { key:\"E\", text:\"Na žlicu, najbolje kad me uhvati ljetni mood\" }\n    ]},\n    { number:4, question:\"Koja rečenica te najbolje opisuje?\", buttonLabel:\"ZAVRŠI KVIZ\", answers:[\n      { key:\"A\", text:\"Volim klasike i teško im odolijevam\" },\n      { key:\"B\", text:\"Nježni okusi su mi uvijek prvi izbor\" },\n      { key:\"C\", text:\"Ako je slatko, neka bude bogato i konkretno\" },\n      { key:\"D\", text:\"Volim sve što je profinjeno, kremasto i fino izbalansirano\" },\n      { key:\"E\", text:\"Najbolje stvari imaju okus ljeta\" }\n    ]}\n  ];\n\n  function computeResult(answers) {\n    var counts = { Duo:0, Milk:0, Gold:0, GoldCreamy:0, Kokos:0 };\n    for (var i = 0; i \u003c answers.length; i++) counts[FLAVOR_MAP[answers[i]]]++;\n    return Object.entries(counts).sort(function(a, b){ return b[1] - a[1]; })[0][0];\n  }\n\n  var state = { screen: \"intro\", answers: [], selected: null };\n\n  function setState(patch) {\n    for (var k in patch) state[k] = patch[k];\n    render();\n  }\n\n  function render() {\n    var root = document.getElementById(\"root\");\n    if (!root) return;\n\n    if (state.screen === \"intro\") {\n      root.innerHTML =\n        '\u003cdiv class=\"screen\"\u003e' +\n          '\u003ch1 class=\"intro-title\"\u003eZABAVNI KVIZ: KOJI SI OKUS LINOLADE?\u003c/h1\u003e' +\n          '\u003cp class=\"intro-subtitle\"\u003eOvaj kviz otkriva koji Lino Lada namaz najbolje paše tvojoj osobnosti, jutarnjim ritualima i slatkim navikama. Odgovori na pitanja i saznaj baš svoj namaz.\u003c/p\u003e' +\n          '\u003cbutton class=\"btn\" id=\"startBtn\"\u003eZAPOČNI KVIZ\u003c/button\u003e' +\n        '\u003c/div\u003e';\n      document.getElementById(\"startBtn\").onclick = function() {\n        setState({ screen: 0, answers: [], selected: null });\n      };\n      return;\n    }\n\n    if (state.screen === \"result\") {\n      var r = RESULTS[computeResult(state.answers)];\n      root.innerHTML =\n        '\u003cdiv class=\"screen\"\u003e' +\n          '\u003ch1 class=\"result-title\"\u003e' + r.title + '\u003c/h1\u003e' +\n          '\u003cp class=\"result-desc\"\u003e' + r.description + '\u003c/p\u003e' +\n          '\u003cbutton class=\"btn\" id=\"restartBtn\"\u003eVRATI NA KVIZ\u003c/button\u003e' +\n        '\u003c/div\u003e';\n      document.getElementById(\"restartBtn\").onclick = function() {\n        setState({ screen: \"intro\", answers: [], selected: null });\n      };\n      return;\n    }\n\n    var qIndex = state.screen;\n    var q = QUESTIONS[qIndex];\n    if (!q) return;\n\n    var answersHTML = \"\";\n    for (var i = 0; i \u003c q.answers.length; i++) {\n      var a = q.answers[i];\n      var sel = state.selected === a.key ? \" selected\" : \"\";\n      answersHTML += '\u003cbutton class=\"answer-btn' + sel + '\" data-key=\"' + a.key + '\"\u003e' + a.key + \") \" + a.text + '\u003c/button\u003e';\n    }\n\n    root.innerHTML =\n      '\u003cdiv class=\"screen\"\u003e' +\n        '\u003cdiv class=\"question-wrap\"\u003e' +\n          '\u003ch2 class=\"question-title\"\u003e' + q.number + '. ' + q.question + '\u003c/h2\u003e' +\n          '\u003cdiv class=\"answers\"\u003e' + answersHTML + '\u003c/div\u003e' +\n          '\u003cdiv class=\"btn-center\"\u003e' +\n            '\u003cbutton class=\"btn\" id=\"nextBtn\"' + (state.selected ? \"\" : \" disabled\") + '\u003e' + q.buttonLabel + '\u003c/button\u003e' +\n          '\u003c/div\u003e' +\n        '\u003c/div\u003e' +\n      '\u003c/div\u003e';\n\n    var answerBtns = root.querySelectorAll(\".answer-btn\");\n    for (var j = 0; j \u003c answerBtns.length; j++) {\n      answerBtns[j].onclick = (function(key) {\n        return function() { setState({ selected: key }); };\n      })(answerBtns[j].dataset.key);\n    }\n\n    document.getElementById(\"nextBtn\").onclick = function() {\n      if (!state.selected) return;\n      var newAnswers = state.answers.concat([state.selected]);\n      var nextScreen = qIndex \u003c 3 ? qIndex + 1 : \"result\";\n      setState({ screen: nextScreen, answers: newAnswers, selected: null });\n    };\n  }\n\n  render();\n});\n\u003c/script\u003e\n\u003c/body\u003e\n\u003c/html\u003e",
