,\n      { key:\"B\", text:\"Tako da prvo tražim bijeli dio\" },\n      { key:\"C\", text:\"Na palačinkama, uz još malo hrskavog dodatka\" },\n      { key:\"D\", text:\"U desertima, kremama i svemu što traži glatku teksturu\" },\n      { key:\"E\", text:\"Na žlicu, najbolje kad me uhvati ljetni mood\" }\n    ]},\n    { number:4, question:\"Koja rečenica te najbolje opisuje?\", buttonLabel:\"ZAVRŠI KVIZ\", answers:[\n      { key:\"A\", text:\"Volim klasike i teško im odolijevam\" },\n      { key:\"B\", text:\"Nježni okusi su mi uvijek prvi izbor\" },\n      { key:\"C\", text:\"Ako je slatko, neka bude bogato i konkretno\" },\n      { key:\"D\", text:\"Volim sve što je profinjeno, kremasto i fino izbalansirano\" },\n      { key:\"E\", text:\"Najbolje stvari imaju okus ljeta\" }\n    ]}\n  ];\n\n  function computeResult(answers) {\n    var counts = { Duo:0, Milk:0, Gold:0, GoldCreamy:0, Kokos:0 };\n    for (var i = 0; i \u003c answers.length; i++) counts[FLAVOR_MAP[answers[i]]]++;\n    return Object.entries(counts).sort(function(a, b){ return b[1] - a[1]; })[0][0];\n  }\n\n  var state = { screen: \"intro\", answers: [], selected: null };\n\n  function setState(patch) {\n    for (var k in patch) state[k] = patch[k];\n    render();\n  }\n\n  function render() {\n    var root = document.getElementById(\"root\");\n    if (!root) return;\n\n    if (state.screen === \"intro\") {\n      root.innerHTML =\n        '\u003cdiv class=\"screen\"\u003e' +\n          '\u003ch1 class=\"intro-title\"\u003eZABAVNI KVIZ: KOJI SI OKUS LINOLADE?\u003c/h1\u003e' +\n          '\u003cp class=\"intro-subtitle\"\u003eOvaj kviz otkriva koji Lino Lada namaz najbolje paše tvojoj osobnosti, jutarnjim ritualima i slatkim navikama. Odgovori na pitanja i saznaj baš svoj namaz.\u003c/p\u003e' +\n          '\u003cbutton class=\"btn\" id=\"startBtn\"\u003eZAPOČNI KVIZ\u003c/button\u003e' +\n        '\u003c/div\u003e';\n      document.getElementById(\"startBtn\").onclick = function() {\n        setState({ screen: 0, answers: [], selected: null });\n      };\n      return;\n    }\n\n    if (state.screen === \"result\") {\n      var r = RESULTS[computeResult(state.answers)];\n      root.innerHTML =\n        '\u003cdiv class=\"screen\"\u003e' +\n          '\u003ch1 class=\"result-title\"\u003e' + r.title + '\u003c/h1\u003e' +\n          '\u003cp class=\"result-desc\"\u003e' + r.description + '\u003c/p\u003e' +\n          '\u003cbutton class=\"btn\" id=\"restartBtn\"\u003eVRATI NA KVIZ\u003c/button\u003e' +\n        '\u003c/div\u003e';\n      document.getElementById(\"restartBtn\").onclick = function() {\n        setState({ screen: \"intro\", answers: [], selected: null });\n      };\n      return;\n    }\n\n    var qIndex = state.screen;\n    var q = QUESTIONS[qIndex];\n    if (!q) return;\n\n    var answersHTML = \"\";\n    for (var i = 0; i \u003c q.answers.length; i++) {\n      var a = q.answers[i];\n      var sel = state.selected === a.key ? \" selected\" : \"\";\n      answersHTML += '\u003cbutton class=\"answer-btn' + sel + '\" data-key=\"' + a.key + '\"\u003e' + a.key + \") \" + a.text + '\u003c/button\u003e';\n    }\n\n    root.innerHTML =\n      '\u003cdiv class=\"screen\"\u003e' +\n        '\u003cdiv class=\"question-wrap\"\u003e' +\n          '\u003ch2 class=\"question-title\"\u003e' + q.number + '. ' + q.question + '\u003c/h2\u003e' +\n          '\u003cdiv class=\"answers\"\u003e' + answersHTML + '\u003c/div\u003e' +\n          '\u003cdiv class=\"btn-center\"\u003e' +\n            '\u003cbutton class=\"btn\" id=\"nextBtn\"' + (state.selected ? \"\" : \" disabled\") + '\u003e' + q.buttonLabel + '\u003c/button\u003e' +\n          '\u003c/div\u003e' +\n        '\u003c/div\u003e' +\n      '\u003c/div\u003e';\n\n    var answerBtns = root.querySelectorAll(\".answer-btn\");\n    for (var j = 0; j \u003c answerBtns.length; j++) {\n      answerBtns[j].onclick = (function(key) {\n        return function() { setState({ selected: key }); };\n      })(answerBtns[j].dataset.key);\n    }\n\n    document.getElementById(\"nextBtn\").onclick = function() {\n      if (!state.selected) return;\n      var newAnswers = state.answers.concat([state.selected]);\n      var nextScreen = qIndex \u003c 3 ? qIndex + 1 : \"result\";\n      setState({ screen: nextScreen, answers: newAnswers, selected: null });\n    };\n  }\n\n  render();\n});\n\u003c/script\u003e\n\u003c/body\u003e\n\u003c/html\u003e",
