      Kokos: {
        title: "Ti si Lino Lada Kokos",
        description: "Ti si ljetni tip, čak i kad je vani oblačno. Voliš okuse koji podsjećaju na more, sunce i lagane slatke trenutke bez puno plana. Lino Lada Kokos, s harmonijom mlijeka i kokosa, tvoj je savršeni match za dane kad želiš da sve ima malo tropskiji vibe."
      },
      Duo: {
        title: "Ti si Lino Lada Duo",
        description: "Ti si klasik s razlogom. Voliš stvari koje imaju priču, okus djetinjstva i onaj prepoznatljivi spoj bijelog i tamnog namaza kojem se uvijek vraćamo. Kod tebe nema puno filozofije: kad je nešto dobro, dobro je zauvijek."
      },
      Milk: {
        title: "Ti si Lino Lada Milk",
        description: "Ti si onaj tip koji je oduvijek prvo išao na bijeli dio. Voliš nježne, mliječne okuse i slatke rituale koji nisu prenapadni, nego baš fino kremasti i lagani. Tvoj idealan trenutak je jednostavan, mekan i sladak taman koliko treba."
      }
    };
    const QUESTIONS = [{
        number: 1,
        question: "Kako izgleda tvoje savršeno jutro?",
        answers: [{
          key: "A",
          text: "Tost, kava i onaj poznati okus koji te odmah vrati u djetinjstvo"
        }, {
          key: "B",
          text: "Lagano, nježno i bez puno kompliciranja"
        }, {
          key: "C",
          text: "Bogato, sporo i s doručkom koji se ne zaboravlja"
        }, {
          key: "D",
          text: "Glatko, kremasto i baš po mom ukusu"
        }, {
          key: "E",
          text: "Sunce, ljeto, otvoren prozor i nešto slatko za početak dana"
        }],
        buttonLabel: "IDUĆE PITANJE"
      },
      {
        number: 2,
        question: "Koji desert te najbolje opisuje?",
        answers: [{
