          text: "Volim sve što je profinjeno, kremasto i fino izbalansirano"
        }, {
          key: "E",
          text: "Najbolje stvari imaju okus ljeta"
        }],
        buttonLabel: "ZAVRŠI KVIZ"
      }
    ];

    function computeResult(a) {
      const c = {
        Duo: 0,
        Milk: 0,
        Gold: 0,
        GoldCreamy: 0,
        Kokos: 0
      };
      for (const x of a) c[FLAVOR_MAP[x]]++;
      return Object.entries(c).sort((a, b) => b[1] - a[1])[0][0];
    }
    let state = {
      screen: "intro",
      answers: [],
      selected: null
    };

    function setState(p) {
      state = Object.assign({}, state, p);
      render();
    }

    function render() {
      const root = document.getElementById("root");
      if (state.screen === "intro") {
        root.innerHTML =
          `<div class="screen"><h1 class="intro-title">ZABAVNI KVIZ: KOJI SI OKUS LINOLADE?</h1><p class="intro-subtitle">Ovaj kviz otkriva koji Lino Lada namaz najbolje paše tvojoj osobnosti, jutarnjim ritualima i slatkim navikama. Odgovori na pitanja i saznaj baš svoj namaz.</p><button class="btn" id="s">ZAPOČNI KVIZ</button></div>`;
        document.getElementById("s").onclick = () => setState({
          screen: 0,
          answers: [],
          selected: null
        });
        return;
      }
      if (state.screen === "result") {
        const r = RESULTS[computeResult(state.answers)];
        root.innerHTML =
          `<div class="screen"><h1 class="result-title">${r.title}</h1><p class="result-desc">${r.description}</p><button class="btn" id="r">VRATI NA KVIZ</button></div>`;
        document.getElementById("r").onclick = () => setState({
          screen: "intro",
          answers: [],
          selected: null
        });
        return;
      }
      const q = QUESTIONS[state.screen];
      root.innerHTML =
        `<div class="screen"><div class="question-wrap"><h2 class="question-title">${q.number}. ${q.question}</h2><div class="answers">${q.answers.map(({key,text})=>` <
        button class = "answer-btn${state.selected===key?"
      selected ":"
      "}"
      data - key = "${key}" > $ {
        key
      }) $ {
      text
    } < /button>`).join("")}</div > < div class = "btn-center" > < button class = "btn"
    id = "n"
    $ {
      state.selected ? "" : "disabled"
    } > $ {
      q.buttonLabel
    } < /button></div > < /div></div > `;
  root.querySelectorAll(".answer-btn").forEach(b=>{b.onclick=()=>setState({selected:b.dataset.key});});
  document.getElementById("n").onclick=()=>{if(!state.selected)return;const a=[...state.answers,state.selected];setState({screen:state.screen<3?state.screen+1:"result",answers:a,selected:null});};
}
render();
  </script>
